    dt_re = re.compile(r"(?<![\w\"'])\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")
    dates = [m.group(0) for m in dt_re.finditer(source)]
    return json.dumps(_encode(parsed, dates), ensure_ascii=False, separators=(",", ":"))


