            "trailing_newline": True, "crlf": False, "allowed_blank_lines": 2}
    opts.update(options or {})
    # Normalize line endings, then format each statement while retaining comments and table order.
    lines = src.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    if opts.get("array_auto_collapse", True):
        lines = _collapse_multiline_arrays(lines, opts.get("array_trailing_comma", True))
    elif opts.get("array_trailing_comma", True):
        depth=0
        for i,line in enumerate(lines):
            delta=_array_depth(line)
            if delta < 0 and depth + delta == 0 and i:
                previous=lines[i-1].rstrip()
                if previous.strip() and not previous.strip().endswith(","):
                    lines[i-1]=previous + ","
            depth += delta
    out=[]
    blank=0
    array_depth=0
    seen_tables=set()
    table_indent=0
    for line in lines:
        s=line.strip()
        if not s:
            blank += 1
            if blank <= int(opts.get("allowed_blank_lines", 2)) and out and out[-1] != "": out.append("")
            continue
        blank=0
        continuation = array_depth > 0
        if s.startswith("#"):
            out.append(s); continue
        if s.startswith("[") and s.endswith("]"):
            if opts.get("indent_tables"):
                header=s.strip("[]")
                parts=[p.strip() for p in header.split(".")]
                parent=".".join(parts[:-1])
                table_indent=(len(parts)-1 if parent in seen_tables else 0)
                s=str(opts.get("indent_string", "  "))*table_indent+s
                seen_tables.add(header)
            out.append(s); continue
        # Locate assignment = outside quoted strings and nested values.
        quote=None; esc=False; depth=0; eq=-1
        for i,c in enumerate(s):
            if quote:
                if esc: esc=False
                elif c=='\\' and quote=='"': esc=True
                elif c==quote: quote=None
            elif c in ('"', "'"): quote=c
            elif c in "[{(": depth+=1
            elif c in "]})": depth-=1
            elif c=="=" and depth==0: eq=i; break
        if eq >= 0:
            key=s[:eq].strip(); val=s[eq+1:].strip()
            # Normalize whitespace around separators inside arrays/inline tables without changing strings.
            val=_normalize(val, bool(opts.get("compact_arrays", True)), bool(opts.get("compact_inline_tables", False)), bool(opts.get("compact_entries", False)))
            if opts.get("reorder_inline_tables"):
                val=_reorder_inline_tables(val, bool(opts.get("compact_inline_tables", False)),
                                           bool(opts.get("compact_entries", False)))
            if opts.get("reorder_arrays"):
                val = _reorder_simple_arrays(val)
            sep="=" if opts.get("compact_entries") else " = "
            s=key + sep + val
            width=int(opts.get("column_width", 80))
            if (opts.get("array_auto_expand", True) and len(s)>width and
                    val.startswith("[") and val.endswith("]")):
                items=_array_items(val[1:-1])
                if items:
                    comma=bool(opts.get("array_trailing_comma", True))
                    pad=str(opts.get("indent_string", "  "))
                    s=key + sep + "[\n" + "\n".join(
                        pad + item + ("," if comma or i < len(items)-1 else "") for i,item in enumerate(items)
                    ) + "\n]"
            entry_indent=table_indent if opts.get("indent_tables") else 0
            if opts.get("indent_entries") and any(x.lstrip().startswith("[") for x in out):
                entry_indent=max(entry_indent, 1)
            if entry_indent:
                s=str(opts.get("indent_string", "  "))*entry_indent+s
        if continuation and not s.startswith("]"):
            s = str(opts.get("indent_string", "  ")) + s
        out.append(s)
        array_depth += _array_depth(line)
    if opts.get("align_entries") or opts.get("align_comments", True):
        _align_entry_groups(out, bool(opts.get("align_entries")),
                            bool(opts.get("align_comments", True)),
                            bool(opts.get("compact_entries", False)))
    if opts.get("reorder_keys"):
        start=0
        while start < len(out):
            if not out[start] or out[start].startswith("#") or out[start].startswith("["):
                start += 1; continue
            end=start
            while end<len(out) and out[end] and not out[end].startswith("#") and not out[end].startswith("["): end+=1
            out[start:end]=sorted(out[start:end], key=lambda x:x.split("=",1)[0].strip())
            start=end
    while out and out[-1]=="": out.pop()
    result="\n".join(out)
    if opts.get("trailing_newline", True) and result: result += "\n"
    if opts.get("crlf"): result=result.replace("\n","\r\n")
    return result

def _top_level_equal(line):
    quote=None; escaped=False; depth=0
    for i,char in enumerate(line):
        if quote:
            if escaped: escaped=False
            elif char=="\\" and quote=='"': escaped=True
            elif char==quote: quote=None
        elif char in ('"', "'"): quote=char
        elif char in "[{(": depth+=1
        elif char in "]})": depth-=1
        elif char=="#": return -1
        elif char=="=" and depth==0: return i
    return -1

def _comment_index(line):
    quote=None; escaped=False
    for i,char in enumerate(line):
        if quote:
            if escaped: escaped=False
            elif char=="\\" and quote=='"': escaped=True
            elif char==quote: quote=None
        elif char in ('"', "'"): quote=char
        elif char=="#": return i
    return -1

def _align_entry_groups(lines, align_entries, align_comments, compact_entries=False):
    i=0
    while i<len(lines):
        eq=_top_level_equal(lines[i])
        if eq<0:
            i+=1; continue
        start=i; group=[]
        while i<len(lines):
            eq=_top_level_equal(lines[i])
            if eq<0: break
            group.append((i, lines[i][:eq].rstrip(), lines[i][eq+1:].lstrip()))
            i+=1
        if len(group)<2: continue
        width=max(len(key.lstrip()) for _,key,_ in group) if align_entries else 0
        sep="=" if compact_entries else " = "
        aligned=[]
        for index,key,value in group:
            prefix=key[:len(key)-len(key.lstrip())]
            clean=key.lstrip()
            aligned.append([index, prefix + clean.ljust(width), value])
        if align_comments:
            targets=[len(key)+len(sep)+_comment_index(value) for _,key,value in aligned if _comment_index(value)>=0]
            if targets:
                target=max(targets)
                for item in aligned:
                    ci=_comment_index(item[2])
                    if ci>=0:
                        current=len(item[1])+len(sep)+ci
                        item[2]=item[2][:ci] + " "*max(0,target-current) + item[2][ci:]
        for index,key,value in aligned:
            lines[index]=key + sep + value

def _array_items(body):
    """Split an array body at commas outside nested values and quoted strings."""
    items=[]; start=0; stack=[]; quote=None; esc=False
    pairs={"]":"[", "}":"{", ")":"("}
    for i,ch in enumerate(body):
        if quote:
            if esc: esc=False
            elif ch=="\\" and quote=='"': esc=True
            elif ch==quote: quote=None
        elif ch in ('"', "'"): quote=ch
        elif ch in "[{(": stack.append(ch)
        elif ch in "]})":
            if stack and stack[-1]==pairs[ch]: stack.pop()
        elif ch=="," and not stack:
            item=body[start:i].strip()
            if item: items.append(item)
            start=i+1
    tail=body[start:].strip()
    if tail: items.append(tail)
    return items

def _reorder_inline_tables(text, compact=False, compact_entries=False):
    result=[]; i=0; quote=None; escaped=False
    while i<len(text):
        ch=text[i]
        if quote:
            result.append(ch)
            if escaped: escaped=False
            elif ch=="\\" and quote=='"': escaped=True
            elif ch==quote: quote=None
            i+=1; continue
        if ch in ('"', "'"):
            quote=ch; result.append(ch); i+=1; continue
        if ch!="{":
            result.append(ch); i+=1; continue
        depth=1; j=i+1; q=None; esc=False
        while j<len(text) and depth:
            c=text[j]
            if q:
                if esc: esc=False
                elif c=="\\" and q=='"': esc=True
                elif c==q: q=None
            elif c in ('"', "'"): q=c
            elif c=="{": depth+=1
            elif c=="}": depth-=1
            j+=1
        if depth:
            result.append(ch); i+=1; continue
        body=text[i+1:j-1]
        entries=[]
        for entry in _array_items(body):
            eq=_top_level_equal(entry)
            if eq<0: entries.append(entry); continue
            key=entry[:eq].strip()
            value=_reorder_inline_tables(entry[eq+1:].strip(), compact, compact_entries)
            sep="=" if compact_entries else " = "
            entries.append((key, key+sep+value))
        entries.sort(key=lambda item: item[0] if isinstance(item, tuple) else item)
        rendered=", ".join(item[1] if isinstance(item, tuple) else item for item in entries)
        pad="" if compact else " "
        result.append("{" + (pad+rendered+pad if rendered else "") + "}")
        i=j
    return "".join(result)

def _array_depth(text):
    quote = None
    escaped = False
    depth = 0
    for char in text:
        if quote:
            if escaped:
                escaped = False
            elif char == "\\" and quote == '"':
                escaped = True
            elif char == quote:
                quote = None
        elif char in ('"', "'"):
            quote = char
        elif char == "#":
            break
        elif char == "[":
            depth += 1
        elif char == "]":
            depth -= 1
    return depth

def _has_comment(text):
    quote=None; escaped=False
    for char in text:
        if quote:
            if escaped: escaped=False
            elif char=="\\" and quote=='"': escaped=True
            elif char==quote: quote=None
        elif char in ('"', "'"):
            quote=char
        elif char=="#":
            return True
    return False

def _collapse_multiline_arrays(lines, trailing_comma=True):
    result = []
    i = 0
    while i < len(lines):
        line = lines[i]
        if _array_depth(line) > 0:
            parts = [line.strip()]
            depth = _array_depth(line)
            i += 1
            while i < len(lines) and depth > 0:
                part = lines[i].strip()
                parts.append(part)
                depth += _array_depth(part)
                i += 1
            if any(_has_comment(part) for part in parts):
                if trailing_comma and parts and parts[-1].strip() == "]":
                    for j in range(len(parts)-2, -1, -1):
                        if parts[j] and not parts[j].lstrip().startswith("#"):
                            if not parts[j].rstrip().endswith(","):
                                parts[j]=parts[j].rstrip()+","

                                parts[j]=parts[j].rstrip()+","
                            break
                result.extend(parts)
                continue
            merged = " ".join(part for part in parts if part)
            merged = re.sub(r",\s*\]", "]", merged)
            result.append(merged)
        else:
            result.append(line)
            i += 1
    return result

def _reorder_simple_arrays(text):
    """Sort simple, single-line array values while leaving nested arrays alone."""
    def replace(match):
        body = match.group(1)
        if "[" in body or "{" in body or "#" in body:
            return "[" + body + "]"
        items = []
        quote = None
        escaped = False
        start = 0
        for i, char in enumerate(body):
            if quote:
                if escaped: escaped = False
                elif char == "\\" and quote == '"': escaped = True
                elif char == quote: quote = None
            elif char in ('"', "'"): quote = char
            elif char == ",":
                item = body[start:i].strip()
                if item: items.append(item)
                start = i + 1
        item = body[start:].strip()
        if item: items.append(item)
        return "[" + ", ".join(sorted(items)) + "]"
    return re.sub(r"\[([^\[\]]*)\]", replace, text)

def _normalize(s, compact_arrays, compact_inline_tables, compact_entries):
    # Normalize separators while retaining quoted strings verbatim.
    res=[]; quote=None; esc=False; stack=[]; pending=False
    for i,c in enumerate(s):
        if quote:
            res.append(c)
            if esc: esc=False
            elif c=='\\' and quote=='"': esc=True
            elif c==quote: quote=None
            continue
        if c in ('"',"'"):
            if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
            pending=False; quote=c; res.append(c); continue
        if c.isspace(): pending=True; continue
        if c=='[':
            if pending and res and not res[-1].isspace() and res[-1] != "[": res.append(" ")
            pending=False; stack.append('['); res.append("[" if compact_arrays else "[ "); continue
        if c=='{':
            if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
            pending=False; stack.append('{'); res.extend("{" if compact_inline_tables else "{ "); continue
        if c==']':
            while res and res[-1]==' ': res.pop()
            if not compact_arrays and res and res[-1] != '[': res.append(' ')
            res.append("]"); pending=False
            if stack: stack.pop()
            continue
        if c=='}':
            while res and res[-1]==' ': res.pop()
            if not compact_inline_tables and res and res[-1]!='{': res.append(" ")
            res.append("}"); pending=False
            if stack: stack.pop()
            continue
        if c==',':
            while res and res[-1]==' ': res.pop()
            res.extend(", "); pending=False; continue
        if c=='=':
            while res and res[-1]==' ': res.pop()
            res.extend("=" if compact_entries else " = "); pending=False; continue
        if c=='#':
            while res and res[-1]==' ': res.pop()
            res.extend(" #" + s[i+1:])
            break
        if pending and res and not res[-1].isspace() and res[-1] not in "[{": res.append(" ")
        pending=False; res.append(c)

    return ''.join(res).strip()

#!/usr/bin/env python3
import sys

def _format_diff(path, original, formatted):
    """Render Taplo's zero based, no context diff output."""
    if original == formatted:
        return ""
    import difflib
    old = original.splitlines()
    new = formatted.splitlines()
    matcher = difflib.SequenceMatcher(None, old, new, autojunk=False)
    result = [f"diff a/{path} b/{path}\n", f"--- a/{path}\n", f"+++ b/{path}\n"]
    red, green, reset = "\x1b[31m", "\x1b[32m", "\x1b[0m"
    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        result.append(f"@@ -{i1},{i2-i1} +{j1},{j2-j1} @@\n")
        if tag in ("equal", "replace", "delete"):
            result.extend(line + "\n" for line in old[i1:i2] if tag == "equal")
            if tag != "equal":
                result.extend(f"{red}-{line}{reset}\n" for line in old[i1:i2])
        if tag in ("insert", "replace"):
            result.extend(f"{green}+{line}{reset}\n" for line in new[j1:j2])
    return "".join(result)
import os

def _format(args):
    import format_impl
    opts={}; files=[]; check=False; diff=False; force=False; i=0
    config_path=os.environ.get("TAPLO_CONFIG"); auto_config=True
    valid_options={"align_entries","align_comments","array_trailing_comma","array_auto_expand","array_auto_collapse","compact_arrays","compact_inline_tables","inline_table_expand","compact_entries","column_width","indent_tables","indent_entries","indent_string","trailing_newline","reorder_keys","reorder_arrays","reorder_inline_tables","allowed_blank_lines","crlf"}
    while i<len(args):
        a=args[i]
        if a in ("-h","--help"):
            import command_help
            command_help.write("format"); return 0
        if a in ("--check",): check=True
        elif a=="--diff": diff=True
        elif a in ("-f","--force"): force=True
        elif a in ("-o","--option"):
            i+=1
            if i>=len(args): return 2
            pair=args[i]
            if "=" not in pair: return 1
            k,v=pair.split("=",1)
            if k not in valid_options: return 1
            if v.lower() in ("true","false"): opts[k]=v.lower()=="true"
            elif v.isdigit(): opts[k]=int(v)
            else: opts[k]=v.strip("\"'")
        elif a.startswith("--option="):
            pair=a[len("--option="):]
            if "=" not in pair:return 1
            k,v=pair.split("=",1)
            if k not in valid_options:return 1
            opts[k]= v.lower()=="true" if v.lower() in ("true","false") else (int(v) if v.isdigit() else v.strip("\"'"))
        elif a=="--no-auto-config": auto_config=False
        elif a.startswith("--config="):
            config_path=a.split("=",1)[1]
        elif a.startswith("-") and a!="-":
            if a in ("-c","--config","--cache-path","--stdin-filepath","--colors"):
                i+=1
                if a in ("-c","--config") and i<len(args): config_path=args[i]
            elif a.startswith("--"): pass
            else: return 2
        else: files.append(a)
        i+=1
    selected=config_path

"""Basic TOML lint command implementation."""
import glob
import datetime
import json
import re
import sys
from urllib.parse import unquote, urlparse

from tomltest import _find_eq, _key_parts, _parse, _strip_comment, _unclosed, _value, _split


def _duplicates(source):
    scopes = {(): {}}
    table = ()
    array_indices = {}
    declared_tables = {}
    for number, raw in enumerate(source.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("[[") and line.endswith("]]" ):
            name = tuple(_key_parts(line[2:-2]))
            array_indices[name] = array_indices.get(name, 0) + 1
            table = ("__array_table__", name, array_indices[name])
            scopes.setdefault(table, {})
            continue
        if line.startswith("[") and line.endswith("]"):
            table = tuple(_key_parts(line[1:-1]))
            if table in declared_tables:
                return (declared_tables[table], number, raw, table, 2)
            declared_tables[table] = number
            scopes.setdefault(table, {})
            continue
        eq = _find_eq(line)
        if eq < 0:
            continue
        parts = _key_parts(line[:eq].strip())
        key = tuple(parts)
        scope = scopes.setdefault(table, {})
        if key in scope:
            return (scope[key], number, raw, parts[0], 1)
        scope[key] = number
    return None


def _report_duplicate(source, filename, duplicate):
    first, second, raw, _key, column = duplicate
    lines = source.splitlines()
    width = len(str(second))
    print("error: conflicting keys", file=sys.stderr)
    print(f"  ┌─ {filename}:{second}:{column}", file=sys.stderr)
    print("  │", file=sys.stderr)
    for number in range(first, second + 1):
        print(f"{number:>{width}} │ {lines[number-1]}", file=sys.stderr)
        if number == first:
            print("  │ " + " " * (column - 1) + "- duplicate found here", file=sys.stderr)
        if number == second:
            print("  │ " + " " * (column - 1) + "^ duplicate key", file=sys.stderr)
    print("", file=sys.stderr)


def _syntax_error(source):
    """Return a rough (line, column, message) for common malformed TOML."""
    pending = ""
    start = 1
    for number, raw in enumerate(source.splitlines(), 1):
        line = _strip_comment(raw).strip()
        if not line or line.startswith("#"):
            continue
        if not pending:
            start = number
        pending = (pending + "\n" + line).strip() if pending else line
        if _unclosed(pending):
            continue
        statement, pending = pending, ""
        if statement.startswith("[") and statement.endswith("]"):
            continue
        eq = _find_eq(statement)
        if eq < 0:
            return number, 1, "expected `=`"
        key = statement[:eq].strip()
        if not key:
            return number, 1, "expected key"
        raw_value = _strip_comment(statement[eq + 1:].strip())
        if not raw_value:
            return number, max(1, raw.find("=") + 2), "expected value"
        try:
            value = _value(raw_value)
        except Exception:
            value = None
        if (re.match(r"^[+-]?(?:\d|\.\d)", raw_value)
                and not isinstance(value, (datetime.datetime, datetime.date, datetime.time))
                and not _valid_number(raw_value)):
            col = raw.find(raw_value) + 1
            return number, max(1, col), "invalid number"
        # Bare text is not a TOML value. Quoted strings and temporal values
        # have distinct parsed representations in the compatibility parser.
        if isinstance(value, str) and not (raw_value.startswith(('"', "'")) and raw_value.endswith(('"', "'"))):
            col = raw.find(raw_value) + 1
            return number, max(1, col), "invalid value"
    if pending:
        line = source.splitlines()[start - 1] if source.splitlines() else ""
        col = max(1, line.find('"') + 1 if '"' in line else 1)
        return start, col, "unexpected end of document"
    return None


def _report_syntax(source, filename, error):
    line_no, col, message = error
    lines = source.splitlines()
    line = lines[line_no - 1] if 0 < line_no <= len(lines) else ""
    if message == "unexpected end of document" and '"' in line:
        quote_col = line.find('"') + 1
        print("error: invalid TOML", file=sys.stderr)
        print(f"  ┌─ {filename}:{line_no}:{quote_col}", file=sys.stderr)
        print("  │", file=sys.stderr)
        print(f"{line_no} │ {line}", file=sys.stderr)
        print("  │ " + " " * (quote_col - 1) + "^ unexpected token\n", file=sys.stderr)
        value_col = quote_col + 1
        print("error: invalid TOML", file=sys.stderr)
        print(f"  ┌─ {filename}:{line_no}:{value_col}", file=sys.stderr)
        print("  │", file=sys.stderr)
        print(f"{line_no} │ {line}", file=sys.stderr)
        print("  │ " + " " * (value_col - 1) + "^" * max(1, len(line) - value_col + 1) + " expected value", file=sys.stderr)
        print("", file=sys.stderr)
        return
    print("error: invalid TOML", file=sys.stderr)
    print(f"  ┌─ {filename}:{line_no}:{col}", file=sys.stderr)
    print("  │", file=sys.stderr)
    print(f"{line_no} │ {line}", file=sys.stderr)
    print("  │ " + " " * (col - 1) + "^ " + message, file=sys.stderr)
    print("", file=sys.stderr)


def _valid_value(value):
    value=value.strip()
    if not value: return False
    if value in ("true","false") or value.lower() in ("inf","+inf","-inf","nan","+nan","-nan"): return True
    if re.fullmatch(r"\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?", value): return True
    if re.fullmatch(r"\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?", value): return True
    if re.match(r"^[+-]?(?:\d|\.\d)", value): return _valid_number(value)
    if value[0] in "\"'": return len(value)>=2 and value[-1]==value[0]
    if value.startswith("[") and value.endswith("]"):
        return all(_valid_value(x) for x in _split(value[1:-1]) if x.strip())
    if value.startswith("{") and value.endswith("}"):
        return all(_find_eq(x)>=0 and _valid_value(x[_find_eq(x)+1:]) for x in _split(value[1:-1]) if x.strip())
    digit=r"(?:0|[1-9](?:_?[0-9])*)"
    if re.fullmatch(r"[+-]?"+digit,value): return True
    if re.fullmatch(r"0[xX][0-9A-Fa-f](?:_?[0-9A-Fa-f])*|0[oO][0-7](?:_?[0-7])*|0[bB][01](?:_?[01])*",value): return True
    float_body=digit+r"(?:\.[0-9](?:_?[0-9])*)?(?:[eE][+-]?"+digit+r")?"
    if ("." in value or "e" in value.lower()) and re.fullmatch(r"[+-]?"+float_body,value): return True
    if re.fullmatch(r"\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?)?", value): return True
    if re.fullmatch(r"\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?", value): return True
