import glob
import json
import os
import sys


def collect_files(patterns, command):
    cwd = os.getcwd()
    paths = []
    for pattern in patterns:
        matches = glob.glob(pattern)
        for path in matches:
            if os.path.isfile(path):
                absolute = os.path.abspath(path)
                if absolute not in paths:
                    paths.append(absolute)
    if paths:
        level = os.environ.get("RUST_LOG", "").lower()
        if not any(x in level for x in ("error", "warn", "off")):
            rendered = json.dumps(paths, ensure_ascii=False)
