def collect_files(patterns, command, config_path=None, auto_config=True):
    cwd = os.getcwd()
    selected = config_path or (os.environ.get("TAPLO_CONFIG") if auto_config else None)
    if not selected and auto_config:
        selected = next((name for name in (".taplo.toml", "taplo.toml") if os.path.isfile(name)), None)
    config = {}
    if selected and os.path.isfile(selected):
        selected = os.path.abspath(selected)
        label = "format_files:load_config" if command == "format" else "load_config"
        _log_info(f"taplo:{label}: found configuration file path={json.dumps(selected, ensure_ascii=False)}")
        try:
            from tomltest import _parse
            config = _parse(open(selected, encoding="utf-8").read())
        except Exception:
            config = {}
    excludes = config.get("exclude", []) if isinstance(config, dict) else []
    if not isinstance(excludes, list):
        excludes = []
    paths = []
    total = 0
    excluded_count = 0
    for pattern in patterns:
        matches = glob.glob(pattern)
        for path in matches:
            if os.path.isfile(path):
                absolute = os.path.abspath(path)
                relative = os.path.relpath(absolute, cwd)
                excluded = any(fnmatch.fnmatchcase(absolute, pattern) or
                               fnmatch.fnmatchcase(relative, pattern) for pattern in excludes
                               if isinstance(pattern, str))
                if absolute not in paths:
                    total += 1
                    if excluded:
                        excluded_count += 1
                    else:
                        paths.append(absolute)
    if paths:
        rendered = json.dumps(paths, ensure_ascii=False)
        _log_info(f"taplo:{command}_files:collect_files: found files total={total} excluded={excluded_count} files={rendered} cwd={json.dumps(cwd, ensure_ascii=False)}")
    return paths
